static void cornelious_apply_layout_defaults(void) {
    for (uint8_t k = 0; k < ARRAY_SIZE(td_defaults); k++) dynamic_keymap_set_tap_dance(td_defaults[k].i, &td_defaults[k].e);
    for (uint8_t k = 0; k < ARRAY_SIZE(qs_defaults); k++) {
        uint32_t v = qs_defaults[k].value;
        qmk_settings_set(qs_defaults[k].qsid, &v, sizeof(v)); // ids this firmware lacks are ignored
    }
}

// Full EEPROM reset (brand-new board, or eeconfig wiped).
void eeconfig_init_user(void) {
    cornelious_apply_layout_defaults();
}

// Vial resets its EEPROM data on the first boot of every new build.
void via_init_kb(void) {
    if (!via_eeprom_is_valid()) {
        eeconfig_init_via();
        cornelious_apply_layout_defaults();
    }
}
